class Solution {
    bool better(const string& a,const string& b){
        return b.empty()||a.size()<b.size()||a.size()==b.size()&&a<b;
    }
    public:string shortestSuperstring(vector<string>& words){
        int n=words.size();
        vector<vector<int>> overlap(n,vector<int>(n));
        for(int i=0;i<n;++i)for(int j=0;j<n;++j)if(i!=j)for(int length=min(words[i].size(),words[j].size());length>=0;--length)if(words[i].substr(words[i].size()-length)==words[j].substr(0,length)){
            overlap[i][j]=length;
            break;
        }
        vector<vector<string>> dp(1<<n,vector<string>(n));
        for(int i=0;i<n;++i)dp[1<<i][i]=words[i];
        for(int mask=1;mask<(1<<n);++mask)for(int last=0;last<n;++last)if(!dp[mask][last].empty())for(int next=0;next<n;++next)if(!(mask&(1<<next))){
            int nextMask=mask|(1<<next);
            string candidate=dp[mask][last]+words[next].substr(overlap[last][next]);
            if(better(candidate,dp[nextMask][next]))dp[nextMask][next]=candidate;
        }
        string answer;
        for(string& candidate:dp.back())if(better(candidate,answer))answer=candidate;
        return answer;
    }
};
